using System.Collections;

/// <summary>
/// PaffH 03.05.22
/// last modified: PaffH 25.09.25
/// </summary>
public class NDXProdIdent
{
    const str languageId_de = 'de';
    const str languageId_en = 'en';
    const str languageId_en_us = 'en-us';

    ProdTable   prodTable;


}

Method.Source:
protected void new()
{
}

static NDXProdIdent construct()
{
    return new NDXProdIdent();
}

/// <summary>
/// PaffH 05.05.25
/// last change: PaffH 11.09.25
/// fill contract from PIM-System
/// </summary>
/// <param name = "_contract"></param>
public static void fillContractFromPIM(InventTable _inventTable, NDXProdIdentControlPanelContract _contract)
{
    const int idArtikelKurzbeschreibung1 = 13350;
    const int idArtikelKurzbeschreibung2 = 72;
    const int idInclMaterial = 33;
    const int idArtikelBeschreibungEN = 21007;
    const str delimiter = ':';

    System.String[] attr = new System.String[1]();
    attr.setValue('attr_zeichnungFuerEtikett_48437', 0);

    D365PIMCoreImportExport d365PIMCoreImportExport = D365PIMCoreImportExport::construct();
    Niedax.PIMCore.Models.Product product_de = d365PIMCoreImportExport.importProduct(_inventTable, languageId_de, '', attr);
    Niedax.PIMCore.Models.Product product_en = d365PIMCoreImportExport.importProduct(_inventTable, languageId_en, '', attr);

    // Artikel-Kurzbeschreibung de 1,2
    str itemBez1 = product_de.textFromcsFeatureTextarea(idArtikelKurzbeschreibung1);
    str itemBez2 = product_de.textFromcsFeatureTextarea(idArtikelKurzbeschreibung2);
    _contract.ParmArtikelkurzbeschreibung_de_CXM_1(itemBez1);
    _contract.ParmArtikelkurzbeschreibung_de_CXM_2(itemBez2); 
    _contract.ParmArtikelkurzbeschreibung_de(strFmt(NDXPlaceholderConstants::FirstSpaceSecond, itemBez1, itemBez2));

    // incl. Material
    itemBez1 = product_de.textFromcsFeatureTextarea(idInclMaterial);
    int pos = strScan(itemBez1, delimiter, 1, strLen(itemBez1));
    if (pos)
    {
        _contract.ParmInclMaterial(strLRTrim(subStr(itemBez1, pos+1, strLen(itemBez1))));
    }
    else
    {
        _contract.ParmInclMaterial(itemBez1);
    }

    // Artikelkurzbeschreibung en
    itemBez1 = product_en.textFromcsFeatureTextarea(idArtikelKurzbeschreibung1);
    itemBez2 = product_en.textFromcsFeatureTextarea(idArtikelKurzbeschreibung2);
    _contract.ParmArtikelkurzbeschreibung_en_us(strFmt(NDXPlaceholderConstants::FirstSpaceSecond, itemBez1, itemBez2));

    // Artikelbeschreibung en
    _contract.ParmArtikelbeschreibung_en_CXM(product_en.artikelbeschreibung);

    // Etikettenbild
    IEnumerable enumerable = product_de.imageList;
    IEnumerator enumerator = enumerable.GetEnumerator();
    while (enumerator.MoveNext())
    {
        Niedax.PIMCore.Models.Images.HotspotImage hotspotImage = enumerator.Current;
        Niedax.PIMCore.Models.Images.Asset asset = hotspotImage.image;
        NDXBase64Content content = asset.data;
        _contract.parmLabelPictureBase64(content);
    }


}

/// <summary>
/// PaffH 03.05.22
/// last modified: PaffH 05.05.25
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_prodTable">ProdTable</param>
/// <returns>NDXProdIdentControlPanelContract</returns>
public static NDXProdIdentControlPanelContract contractFromItemId(ItemId _itemId, ProdTable _prodTable)
{
    NDXProdIdentControlPanelContract contract;
    contract = new NDXProdIdentControlPanelContract();

    contract.ParmProdId(_prodTable.ProdId);
    contract.ParmItemId(_itemId);
    contract.ParmInventColorId(_prodTable.inventDim().InventColorId);
    InventTable inventTable = InventTable::find(_itemId);
    if (inventTable)
    {
        contract.ParmModellNumber(inventTable.NDXModelNumber);
        contract.ParmUK(inventTable.DataAreaId);

        // TODO PaffH: Begin: AX2009.classes.NDX_ProdIdent.fillControlPanelAdditionInventTable()
        NDXProdIdent::fillContractFromPIM(inventTable, contract);

        contract.ParmArtikelkurzbeschreibung_de_CXM_1('Dummy_Artikelkurzbeschreibung_de_CXM_1');
        contract.ParmArtikelkurzbeschreibung_de_CXM_2('Dummy_Artikelkurzbeschreibung_de_CXM_2');
        contract.ParmEtikettentyp('Dummy_Etikettentyp');
        contract.ParmItemName1_en_us('Dummy_Artikelname');
        contract.ParmArtikelbild('Dummy_Artikelbild');
        //contract.ParmURLOPK(false);
        //contract.ParmInclMaterial(false);
        // TODO PaffH: End: AX2009.classes.NDX_ProdIdent.fillControlPanelAdditionInventTable()

        // language specific de
        EcoResProduct ecoResProduct = inventTable.Product();
        EcoResProductTranslation ecoResProductTranslation = EcoResProductTranslation::findByProductLanguage(ecoResProduct.RecId, languageId_de);
        contract.ParmItemName1_de(ecoResProductTranslation.NDXProductName1);
        contract.ParmItemName2_de(ecoResProductTranslation.NDXProductName2);
        contract.ParmArtikelkurzbeschreibung_de(ecoResProductTranslation.Description);
        contract.ParmItemDescription(strFmt('%1, %2', ecoResProductTranslation.NDXProductName1, ecoResProductTranslation.NDXProductName2));
        // language specific en-us
        ecoResProductTranslation = EcoResProductTranslation::findByProductLanguage(ecoResProduct.RecId, languageId_en_us);
        contract.ParmItemName1_en_us(ecoResProductTranslation.NDXProductName1);
        contract.ParmItemName2_en_us(ecoResProductTranslation.NDXProductName2);
        contract.ParmArtikelkurzbeschreibung_en_us(ecoResProductTranslation.Description);

        // item barcode
        InventItemBarcode inventItemBarcode = InventItemBarcode::findPrintItemId(inventTable.ItemId, 'EAN13');
        contract.ParmEAN(inventItemBarcode.itemBarCode);
    }
    return contract;
}

/// <summary>
/// PaffH 03.05.22
/// populate a list with NDXProdIdentControlPanelContract
/// </summary>
/// <param name = "_contract">NDXProdStatusChangedGenerateTransportLabelEventContract</param>
/// <returns>list with NDXProdIdentControlPanelContract</returns>
public List fillFromProdStatusChangedGenerateTransportLabelEventContract(NDXProdStatusChangedGenerateTransportLabelEventContract _contract)
{

    List lines = new List(Types::Class);
    ProdTable lProdTable = ProdTable::find(_contract.ParmProdId());
    if (lProdTable)
    {
        lines = NDXProdIdent::fillControlPanelFromProdTable(lProdTable, _contract, true);
    }
    return lines;
}

/// <summary>
/// PaffH 04.05.22
/// save list with NDXProdIdentControlPanelContract to table NDXProdIdentControlPanel
/// </summary>
/// <param name = "lines">List</param>
public void save2NDXProdIdentControlPanel(List lines)
{
    ListEnumerator listEnum = lines.getEnumerator();
    while (listEnum.moveNext())
    {
        if (listEnum.current() is NDXProdIdentControlPanelContract)
        {
            NDXProdIdentControlPanel::fillFromContract(listEnum.current() as NDXProdIdentControlPanelContract, true);
        }
    }
}

/// <summary>
/// PaffH 02.06.22
/// </summary>
/// <param name = "_prodTable">ProdTable</param>
/// <returns>ProdTable</returns>
public ProdTable parmProdTable(ProdTable _prodTable = prodTable)
{
    prodTable = _prodTable;
    return prodTable;
}

/// <summary>
/// PaffH 05.08.24
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_nDXProdIdentRelevantFor">NDXProdIdentRelevantFor</param>
/// <returns>Query</returns>
static Query queryFromProdIdentTechnique(ItemId _itemId, NDXProdIdentRelevantFor _nDXProdIdentRelevantFor = NDXProdIdentRelevantFor::Verpackungsetikett)
{
    Query q = new Query();
    QueryBuildDataSource qbdsProcedureTable = q.addDataSource(tableNum(NDXProdIdentProcedureTable));
    qbdsProcedureTable.addRange(fieldNum(NDXProdIdentProcedureTable, InventTable)).value(queryValue(InventTable::find(_itemId).RecId));
    QueryBuildDataSource qbdsProdIdentProcedureLine1 = qbdsProcedureTable.addDataSource(tableNum(NDXProdIdentProcedureLine1));
    qbdsProdIdentProcedureLine1.relations(true);
    QueryBuildDataSource qbdsProdIdentProcedureLine2 = qbdsProdIdentProcedureLine1.addDataSource(tableNum(NDXProdIdentProcedureLine2));
    qbdsProdIdentProcedureLine2.relations(true);
    QueryBuildDataSource qbdsProdIdentTechnique = qbdsProdIdentProcedureLine2.addDataSource(tableNum(NDXProdIdentTechnique));
    qbdsProdIdentTechnique.relations(true);
    qbdsProdIdentTechnique.addRange(fieldNum(NDXProdIdentTechnique, RelevantFor)).value(queryValue(_nDXProdIdentRelevantFor));
    return q;
}

/// <summary>
/// PaffH 09.06.22
/// AX2009: classes.NDX_ProdIdent::queryFromProcL2()
/// </summary>
/// <param name = "prodTable">ProdTable</param>
/// <returns>Query</returns>
static Query queryFromProcL2(ProdTable prodTable = null)
{
    Query q = new Query();

    // ProdTable
    QueryBuildDataSource qbdsProdTable = q.addDataSource(tablenum(ProdTable));
    if (prodTable)
    {
        qbdsProdTable.addRange(fieldnum(ProdTable, ProdId)).value(prodTable.ProdId);
    }

    // ProdRoute
    QueryBuildDataSource qbdsProdRoute = qbdsProdTable.addDataSource(tablenum(ProdRoute));
    qbdsProdRoute.relations(true);
    qbdsProdRoute.joinMode(JoinMode::InnerJoin);
    qbdsProdRoute.fetchMode(QueryFetchMode::One2One);

    //RouteOpr
    QueryBuildDataSource qbdsRouteOpr = qbdsProdRoute.addDataSource(tablenum(RouteOpr));
    qbdsRouteOpr.relations(true);
    qbdsRouteOpr.joinMode(JoinMode::InnerJoin);
    qbdsRouteOpr.fetchMode(QueryFetchMode::One2One);

    // RouteTable
    QueryBuildDataSource qbdsRouteTable = qbdsRouteOpr.addDataSource(tablenum(RouteTable));
    qbdsRouteTable.relations(true);
    qbdsRouteTable.joinMode(JoinMode::InnerJoin);
    qbdsRouteTable.fetchMode(QueryFetchMode::One2One);

    //RouteVersion
    QueryBuildDataSource qbdsRouteVersion = qbdsRouteTable.addDataSource(tablenum(RouteVersion));
    qbdsRouteVersion.relations(true);
    qbdsRouteVersion.joinMode(JoinMode::InnerJoin);
    qbdsRouteVersion.fetchMode(QueryFetchMode::One2One);

    // Route
    QueryBuildDataSource qbdsRoute = qbdsRouteTable.addDataSource(tablenum(Route));
    qbdsRoute.relations(true);
    qbdsRoute.joinMode(JoinMode::InnerJoin);
    qbdsRoute.fetchMode(QueryFetchMode::One2One);

    // nDXProdIdentProcedureLine1
    QueryBuildDataSource qbdsNDXProdIdentProcedureLine1 = qbdsRoute.addDataSource(tablenum(NDXProdIdentProcedureLine1));
    qbdsNDXProdIdentProcedureLine1.relations(true);
    qbdsNDXProdIdentProcedureLine1.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureLine1.fetchMode(QueryFetchMode::One2One);

    // nDXProdIdentProcedureLine1
    QueryBuildDataSource qbdsNDXProdIdentProcedureLine2 = qbdsNDXProdIdentProcedureLine1.addDataSource(tablenum(NDXProdIdentProcedureLine2));
    qbdsNDXProdIdentProcedureLine2.relations(true);
    qbdsNDXProdIdentProcedureLine2.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureLine2.fetchMode(QueryFetchMode::One2One);

    // NDX_ProdIdent_ProcedureTable
    QueryBuildDataSource qbdsNDXProdIdentProcedureTable = qbdsNDXProdIdentProcedureLine1.addDataSource(tablenum(NDXProdIdentProcedureTable));
    qbdsNDXProdIdentProcedureTable.relations(true);
    qbdsNDXProdIdentProcedureTable.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureTable.fetchMode(QueryFetchMode::One2One);

    // NDX_ProdIdent_ProcedureTable > ProdTable
    // Sinn der folgenden 2 Zeilen nicht erkannt
    //QueryBuildRange qbr = qbdsNDXProdIdentProcedureTable.addRange(fieldnum(NDXProdIdentProcedureTable, ItemId));
    //qbr.value(strfmt("((%1.%3 == %2.%3))", qbdsNDXProdIdentProcedureTable.name(), qbdsProdTable.name(), fieldid2name(tablenum(ProdTable), fieldnum(prodTable, ItemId))));

    // nDXProdIdentTechnique
    QueryBuildDataSource qbdsNDXProdIdentTechnique = qbdsNDXProdIdentProcedureLine2.addDataSource(tablenum(NDXProdIdentTechnique));
    qbdsNDXProdIdentTechnique.relations(true);
    qbdsNDXProdIdentTechnique.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentTechnique.fetchMode(QueryFetchMode::One2One);
    qbdsNDXProdIdentTechnique.addRange(fieldnum(NDXProdIdentTechnique, RelevantFor)).value(QueryValue(NDXProdIdentRelevantFor::Verpackungsetikett));

    // NDX_ProdIdent_Label
    QueryBuildDataSource qbdsNDXProdIdentLabel = qbdsNDXProdIdentProcedureLine2.addDataSource(tablenum(NDXProdIdentLabel));
    qbdsNDXProdIdentLabel.relations(true);
    qbdsNDXProdIdentLabel.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentLabel.fetchMode(QueryFetchMode::One2One);

    // UnitConvert
    QueryBuildDataSource qbdsUnitOfMeasureConversion = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(UnitOfMeasureConversion));
    qbdsUnitOfMeasureConversion.relations(true); 
    qbdsUnitOfMeasureConversion.joinMode(JoinMode::OuterJoin);
    qbdsUnitOfMeasureConversion.fetchMode(QueryFetchMode::One2One);

    return q;
}

/// <summary>
/// PaffH 09.06.22
/// AX2009: classes.NDX_ProdIdent.fillControlPanelFromProdTable()
/// </summary>
/// <param name = "_prodTable">ProdTable</param>
/// <param name = "_contract">NDXProdStatusChangedGenerateTransportLabelEventContract</param>
/// <param name = "_forceBuild">boolean</param>
/// <returns>List</returns>
static List fillControlPanelFromProdTable(ProdTable _prodTable, NDXProdStatusChangedGenerateTransportLabelEventContract _contract, boolean _forceBuild = false)
{
    List lines = new List(Types::Class);
    List linesProdIdent = new List(Types::Class);
    ProdTable   lProdTable2;
    FormDataSource  fds;
    int anz1, anz2, anzPA, anzLabelForPA;

    fds = FormDataUtil::getFormDataSource(_prodTable);
    for (lProdTable2 = fds && fds.getFirst(true) ? fds.getFirst(true) : _prodTable;
    lProdTable2;
    lProdTable2 = fds ? fds.getNext() : null)
    {
        anz1 = 0;
        anz2 = 0;
        ++anzPA;

        // label info based on "Produktkennzeichnung"
        linesProdIdent = NDXProdIdent::fillControlPanelFromProcL2_Q(NDXProdIdent::queryFromProcL2(lProdTable2), lProdTable2, _contract, _forceBuild);
        anz1 += linesProdIdent.elements();
        lines.appendList(linesProdIdent);

        if (anz1 && anz2)
        {
            NDXProdIdentControlPanel::setSyncActionDiffDataFrom(lProdTable2.ProdId);
        }
        anzLabelForPA += (anz1 || anz2) ? 1 : 0;

        NDXProdTable2ProdIdent::checkProdTable(lProdTable2.ProdId);
    }
    lines = NDXProdIdentControlPanel::refreshListWithContracts(lines);

    return lines;
}

/// <summary>
/// PaffH 09.06.22
/// modified: 18.10.24
/// AX2009: classes.NDX_ProdIdent::fillControlPanelFromProcL2_Q()
/// </summary>
/// <param name = "_q">Query</param>
/// <param name = "_prodTableBuffer">ProdTable</param>
/// <param name = "_contract">NDXProdStatusChangedGenerateTransportLabelEventContract</param>
/// <param name = "_forceBuild">boolean</param>
/// <returns>List</returns>
static List fillControlPanelFromProcL2_Q(Query _q,
                                    ProdTable   _prodTableBuffer,
                                    NDXProdStatusChangedGenerateTransportLabelEventContract _contract,
                                    boolean _forceBuild = false)
{
    NDXProdIdentProcedureTable    nDXProdIdentProcedureTable;
    NDXProdIdentProcedureLine1    nDXProdIdentProcedureLine1;
    NDXProdIdentProcedureLine2    nDXProdIdentProcedureLine2;
    NDXProdIdentTechnique         nDXProdIdentTechnique;
    ProdTable                       prodTable;
    ProdRoute                       prodRoute;
    Route route;
    //UnitConvert                     unitConvert;
    UnitOfMeasureConversion unitOfMeasureConversion;
    NDXProdIdentControlPanel       nDXProdIdentControlPanel;
    List listContracts = new List(Types::Class);
    List listRecords = new List(Types::Record);
    boolean lFirst = true;
    RefRecId refRecIdParent;
    int anz;
    QueryRun    qr;

    qr = new QueryRun(_q);
    while (qr.next())
    {
        nDXProdIdentProcedureTable    = qr.get(tablenum(NDXProdIdentProcedureTable));
        nDXProdIdentProcedureLine1    = qr.get(tablenum(NDXProdIdentProcedureLine1));
        nDXProdIdentProcedureLine2    = qr.get(tablenum(NDXProdIdentProcedureLine2));
        nDXProdIdentTechnique         = qr.get(tablenum(NDXProdIdentTechnique));
        prodRoute                       = qr.get(tablenum(ProdRoute));
        prodTable                       = qr.get(tablenum(ProdTable));
        route = qr.get(tableNum(Route));
        unitOfMeasureConversion = qr.get(tableNum(UnitOfMeasureConversion));

        if (prodRoute.OprId != route.oprid)
        {
            continue;
        }

        nDXProdIdentControlPanel = NDXProdIdentControlPanel::findProcedureLine2(prodTable.ProdId, nDXProdIdentProcedureLine2.RecId, true);
        if (_forceBuild && nDXProdIdentControlPanel)
        {
            switch (true)
            {
                case !nDXProdIdentControlPanel.BT_RecordId :
                    //Warning(strFmtLB(strfmt("@NXD9840", prodTable.ProdId)));            // Es besteht bereits ein BT-Transfer-DS zum PA [%1].\nDieser wurde noch nicht mit BT abgeglichen.\nTransfer zum BT per Sync.
                    break;
                case  nDXProdIdentControlPanel.Active == NoYes::Yes :
                    //Warning(strFmtLB(strfmt("@NXD9839", prodTable.ProdId)));            // Es besteht bereits ein BT-Transfer-DS zum PA [%1].\nTransfer zum BT per Sync.
                    break;
                default :
                    // create new record
                    nDXProdIdentControlPanel.clear();
            }
        }
        if (!nDXProdIdentControlPanel)
        {
            nDXProdIdentControlPanel.initValue();
            nDXProdIdentControlPanel.ProdId                             = prodTable.ProdId;
            nDXProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2   = nDXProdIdentProcedureLine2.RecId;
            nDXProdIdentControlPanel.ControlPanelDataFrom               = NDXProdIdentControlPanelDataFrom::ProdIdent;
            nDXProdIdentControlPanel.Host                               = _contract.ParmHost();
        }
        else
        {
            if (nDXProdIdentControlPanel.ControlPanelDataFrom == NDXProdIdentControlPanelDataFrom::BoxLabelMapping)
            {
                nDXProdIdentControlPanel.ControlPanelDataFrom = NDXProdIdentControlPanelDataFrom::ProdIdentAndBoxLabelMapping;
            }
        }


        nDXProdIdentControlPanel.OprId                             = prodRoute.OprId;
        nDXProdIdentControlPanel.OprNum                            = prodRoute.OprNum;
        nDXProdIdentControlPanel.ItemId                            = prodTable.ItemId;
        nDXProdIdentControlPanel.InventRefId = prodTable.InventRefId;
        nDXProdIdentControlPanel.Uebertragung_aus_AX = DateTimeUtil::utcNow();
        nDXProdIdentControlPanel.LabelId                           = NDXProdIdentLabel::findRecId(nDXProdIdentProcedureLine2.NDXProdIdentLabel).ID;
        nDXProdIdentControlPanel.RouteId                           = prodTable.RouteId;
        nDXProdIdentControlPanel.AnzahlEtiketten                   = real2int(RoundUp(prodTable.QtySched
                                                                    / (unitOfMeasureConversion.Factor ? unitOfMeasureConversion.Factor : 1), 1));

        nDXProdIdentControlPanel.TechniqueID                       = NDXProdIdentTechnique::findRecId(nDXProdIdentProcedureLine2.NDXProdIdentTechnique).ID;
        nDXProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2  = nDXProdIdentProcedureLine2.RecId;
        nDXProdIdentControlPanel.RefRecIdUnitConvert = unitOfMeasureConversion.RecId;
        nDXProdIdentControlPanel.LabelIdProdIdent                  = nDXProdIdentControlPanel.LabelId;
        nDXProdIdentControlPanel.LabelFoundOK                      = true;
        nDXProdIdentControlPanel.OprIdOK                           = prodRoute.RecId != 0;
        nDXProdIdentControlPanel.OprNumOK                          = prodRoute.RecId != 0;
        nDXProdIdentControlPanel.ProdIdentExists                   = true;

        nDXProdIdentControlPanel.InventColorId                     = prodTable.inventDim().InventColorId;            

        NDXProdIdent::fillControlPanelAddition(nDXProdIdentControlPanel);
        NDXProdIdent::setStatus(nDXProdIdentControlPanel, _prodTableBuffer, _forceBuild);

        ttsbegin;
        if (nDXProdIdentControlPanel.validateWrite())
        {
            ++anz;
            nDXProdIdentControlPanel.write();
            listContracts.addEnd(NDXProdIdentControlPanel::populateToContract(nDXProdIdentControlPanel));
            if (lFirst)
            {
                refRecIdParent = nDXProdIdentControlPanel.RecId;
                lFirst = false;
            }
            listRecords.addEnd(nDXProdIdentControlPanel);
        }
        ttscommit;
    }
    NDXProdIdentControlPanelLine::fillFromRecordList(refRecIdParent, listRecords);
    return listContracts;
}

/// <summary>
/// PaffH 05.07.22
/// last modified: PaffH 11.09.25
/// AX2009: classes.NDX_ProdIdent::fillControlPanelAddition()
/// </summary>
/// <param name = "nDX_ProdIdentControlPanel">NDXProdIdentControlPanel</param>
/// <param name = "isManual">boolean</param>
static void fillControlPanelAddition(NDXProdIdentControlPanel nDX_ProdIdentControlPanel, boolean isManual = false)
{
    InventTable                     inventTable;
    UnitOfMeasureConversion         unitOfMeasureConversion;
    UnitOfMeasure                   unitOfMeasure;
    UnitOfMeasureTranslation        unitOfMeasureTranslation;
    EcoResPhysicalProductDimensions ecoResPhysicalProductDimensions;
    ProdTable                       prodTable = ProdTable::find(nDX_ProdIdentControlPanel.ProdId);
    nDXProdIdentProcedureLine2      nDXProdIdentProcedureLine2;

    SalesLine                       salesLine;
    CustTable                       custTable;
    CustVendExternalItem            custVendExternalItem;
    container       conData;
    int             i;

    inventTable = InventTable::find(NDXProdIdentOZMapping::getMappedItemIdActiv(nDX_ProdIdentControlPanel.ItemId, true));
    if (inventTable.ItemId != nDX_ProdIdentControlPanel.ItemId)
    {
        nDX_ProdIdentControlPanel.OZMappedBy = inventTable.ItemId;
    }

    if (nDX_ProdIdentControlPanel.RefRecIdUnitConvert)
    {
        select firstonly unitOfMeasureConversion
            where unitOfMeasureConversion.RecId == nDX_ProdIdentControlPanel.RefRecIdUnitConvert;
    }

    if (nDX_ProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2)
    {
        select nDXProdIdentProcedureLine2
        where nDXProdIdentProcedureLine2.RecId == nDX_ProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2;

        // PaffH 27.04.23: ProdRouteJob.JobId legacy:12 signs, now: 'PRV' + 6 signs - not usable for Barcode
        //if(!isManual)
        //{
        //    nDX_ProdIdentControlPanel.ProdLabelId = nDXProdIdentProcedureLine1.getProdLabelIdBarcode(prodTable.ProdId, false);
        //}
        //else
        nDX_ProdIdentControlPanel.ProdLabelId = NDXProdIdentControlPanel::genBarcodeString(false);
        nDX_ProdIdentControlPanel.fillFromBlock2ItemId(nDXProdIdentProcedureLine2);
    }

    NDXProdIdent::fillControlPanelAdditionInventTable(nDX_ProdIdentControlPanel, inventTable);
    nDX_ProdIdentControlPanel.Etikettentyp      = nDX_ProdIdentControlPanel.LabelId;

    // Einheit
    //unitOfMeasure = UnitOfMeasure::find(unitOfMeasureConversion.FromUnitOfMeasure); // in AX2009 FROM, in D365FO TO 
    unitOfMeasure = UnitOfMeasure::find(unitOfMeasureConversion.ToUnitOfMeasure);
    unitOfMeasureTranslation = unitOfMeasureTranslation::findByTranslation(unitOfMeasure.RecId, languageId_de);
    nDX_ProdIdentControlPanel.Einheit_de        = unitOfMeasureTranslation.Description;

    unitOfMeasureTranslation = unitOfMeasureTranslation::findByTranslation(UnitOfMeasure::find(unitOfMeasureConversion.FromUnitOfMeasure).RecId, languageId_en);
    nDX_ProdIdentControlPanel.Einheit_en_us     = unitOfMeasureTranslation.Description;

    ecoResPhysicalProductDimensions = EcoResPhysicalProductDimensions::find(inventTable.Product, unitOfMeasure.Symbol, EcoResPhysicalDimensionType::Packing);

    nDX_ProdIdentControlPanel.VP_Stufe          = unitOfMeasureConversion.NDXUnitLevel;
    nDX_ProdIdentControlPanel.VP_VonEinheitFaktor   = real2int(unitOfMeasureConversion.Factor);

    //nDX_ProdIdentControlPanel.VP_VonEinheit     = UnitOfMeasure::find(unitOfMeasureConversion.FromUnitOfMeasure).Symbol;
    //nDX_ProdIdentControlPanel.VP_InEinheit      = UnitOfMeasure::find(unitOfMeasureConversion.ToUnitOfMeasure).Symbol;
    nDX_ProdIdentControlPanel.VP_VonEinheit     = UnitOfMeasure::find(unitOfMeasureConversion.ToUnitOfMeasure).Symbol;
    nDX_ProdIdentControlPanel.VP_InEinheit      = UnitOfMeasure::find(unitOfMeasureConversion.FromUnitOfMeasure).Symbol;

    nDX_ProdIdentControlPanel.Artikelbild = NDXProdIdentPictureItemIdMapping::findActive(inventTable.ItemId).ItemPictureName;
    FilePath filePath;
    Filename fileType;
    [filePath, nDX_ProdIdentControlPanel.ArtikelbildExclExt, fileType] = fileNameSplit(nDX_ProdIdentControlPanel.Artikelbild);

    // Prüfzeichen
    conData = NDXProdIdentBlock2ItemId::getDataFromBlockType(NDXProdIdentBlockType::CertificationMark, nDXProdIdentProcedureLine2);
    for (i=1; i<=conlen(conData); i++)
    {
        switch (i)
        {
            case 1: 
                nDX_ProdIdentControlPanel.Pruefzeichen1 = conpeek(conData,i); 
                break;
            case 2: 
                nDX_ProdIdentControlPanel.Pruefzeichen2 = conpeek(conData,i); 
                break;
            case 3: 
                nDX_ProdIdentControlPanel.Pruefzeichen3 = conpeek(conData,i); 
                break;
            case 4: 
                nDX_ProdIdentControlPanel.Pruefzeichen4 = conpeek(conData,i); 
                break;
            case 5: 
                nDX_ProdIdentControlPanel.Pruefzeichen5 = conpeek(conData,i); 
                break;
        }
    }

    // Logo
    conData = NDXProdIdentBlock2ItemId::getDataFromBlockType(NDXProdIdentBlockType::Logo, nDXProdIdentProcedureLine2);
    for (i=1; i<=conlen(conData); i++)
    {
        switch (i)
        {
            case 1: 
                nDX_ProdIdentControlPanel.Logo1 = conpeek(conData,i); 
                break;
            case 2: 
                nDX_ProdIdentControlPanel.Logo2 = conpeek(conData,i); 
                break;
        }
    }

    // Kundenbezug vorhanden?
    if (!isManual &&
    prodTable.InventRefTransId  &&
    prodTable.InventRefId       &&
    prodTable.InventRefType == InventRefType::Sales)
    {
        select firstonly salesLine
        where   salesLine.InventTransId == prodTable.InventRefTransId
            &&  salesLine.SalesId == prodtable.InventRefId
            &&  salesLine.SalesStatus == SalesStatus::Backorder
        join        custTable
            where   custTable.AccountNum == salesLine.CustAccount
        outer join  custVendExternalItem
            where   custVendExternalItem.ModuleType == ModuleInventPurchSalesVendCustGroup::Cust
                &&  custVendExternalItem.CustVendRelation == custTable.AccountNum;
        // Artikel-Debitorengruppe
        if (custTable.CustItemGroupId)
        {
            nDX_ProdIdentControlPanel.Artikel_DebitorenGruppe = custTable.CustItemGroupId;
        }
        if (custVendExternalItem)
        {
            // Externe Artikelnummer
            nDX_ProdIdentControlPanel.ExterneArtikelnummer = custVendExternalItem.ExternalItemId;
            // Externe EAN
            //PaffH 03.01.25 Feld ist in D365FO nicht implementiert
            //nDX_ProdIdentControlPanel.ExterneEAN            = custVendExternalItem.NDX_itemBarCode;
        }
    }

    if(!isManual)                                                         
    {
        nDX_ProdIdentControlPanel.fillFromProdRouteJob();                 
    }

    NDXProdIdent::fillControlPanelAdditionNDX_RicoMap_ItemId(nDX_ProdIdentControlPanel, inventTable);

    if(!isManual)                                                         
    {
        nDX_ProdIdentControlPanel.InventRefId   = prodTable.InventRefId;  
    }
}

