/// <summary>
/// PaffH 05.07.22
/// last modified: PaffH 25.09.25
/// AX2009: classes.NDX_ProdIdent::fillControlPanelAdditionInventTable()
/// </summary>
/// <param name = "nDX_ProdIdentControlPanel">NDXProdIdentControlPanel</param>
/// <param name = "inventTable">InventTable</param>
static void fillControlPanelAdditionInventTable(NDXProdIdentControlPanel nDX_ProdIdentControlPanel, InventTable inventTable)
{
    EcoResProduct ecoResProduct = EcoResProduct::find(inventTable.Product);

    NDXProdIdentControlPanelContract contract = new NDXProdIdentControlPanelContract();
    NDXProdIdent::fillContractFromPIM(inventTable, contract);

    nDX_ProdIdentControlPanel.ArtikelbildBase64 = contract.parmLabelPictureBase64();

    if (contract.ParmArtikelkurzbeschreibung_de())
    {
        nDX_ProdIdentControlPanel.Artikelkurzbeschreibung_de = contract.ParmArtikelkurzbeschreibung_de();
        nDX_ProdIdentControlPanel.Artikelkurzbeschreibung_de_CXM_1 = contract.ParmArtikelkurzbeschreibung_de_CXM_1();
        nDX_ProdIdentControlPanel.Artikelkurzbeschreibung_de_CXM_2 = contract.ParmArtikelkurzbeschreibung_de_CXM_2();
    }
    else
    {
        nDX_ProdIdentControlPanel.Artikelkurzbeschreibung_de = ecoResProduct.productDescription(languageId_de);
    }

    // Artikelkurzbeschreibung EN
    if (contract.ParmArtikelkurzbeschreibung_en_us())
    {
        nDX_ProdIdentControlPanel.Artikelkurzbeschreibung_en_us = contract.ParmArtikelkurzbeschreibung_en_us();
    }
    else
    {
        nDX_ProdIdentControlPanel.Artikelkurzbeschreibung_en_us = ecoResProduct.productDescription(languageId_en_us);
    }
    nDX_ProdIdentControlPanel.PIMItemDescriptionEN = contract.ParmArtikelbeschreibung_en_CXM();

    nDX_ProdIdentControlPanel.Etikettentyp      = nDX_ProdIdentControlPanel.LabelId;

    // englischer Artikelname 1 und 2
    nDX_ProdIdentControlPanel.Artikelname1_en_us = ecoResProduct.NDXProductName1(languageId_en_us);
    nDX_ProdIdentControlPanel.Artikelname2_en_us = ecoResProduct.NDXProductName2(languageId_en_us);

    // deutscher Artikelname 1 und 2
    nDX_ProdIdentControlPanel.Artikelname1_de   = ecoResProduct.NDXProductName1(languageId_de);
    nDX_ProdIdentControlPanel.Artikelname2_de   = ecoResProduct.NDXProductName2(languageId_de);

    nDX_ProdIdentControlPanel.Artikelbeschreibung   = strfmt("@NDXBase:NDXPlaceholder01", nDX_ProdIdentControlPanel.Artikelname1_de, nDX_ProdIdentControlPanel.Artikelname2_de);
    nDX_ProdIdentControlPanel.ModellNummer      = inventTable.NDXModelNumber;
    nDX_ProdIdentControlPanel.EAN               = inventTable.NDXItemBarcode();
    nDX_ProdIdentControlPanel.UK                = inventTable.dataAreaId;

    // URL OPK
    nDX_ProdIdentControlPanel.URLOPK = NDXMagentoBase::getItemOPKWEBAddress(inventTable.NDXModelNumber, languageId_de);

    //InclZub
    nDX_ProdIdentControlPanel.InclMaterial = contract.ParmInclMaterial();
}

/// <summary>
/// PaffH 06.07.22
/// AX2009: classes.NDX_ProdIdent.queryFromProdTable()
/// </summary>
/// <param name = "prodTable">ProdTable</param>
/// <returns>Query</returns>
static Query queryFromProdTable(ProdTable prodTable)
{
    Query   q;
    QueryBuildDataSource    qbds1, qbds2, qbds3, qbds4, qbds5, qbds6;
    ;
    q = new Query();

    // ProdTable
    qbds1 = q.addDataSource(tablenum(prodTable));
    qbds1.addRange(fieldnum(ProdTable, RecId)).value(QueryValue(prodTable.RecId));

    // ProdBOM
    qbds2 = qbds1.addDataSource(tablenum(ProdBOM));
    qbds2.addLink(fieldnum(ProdTable, ProdId), fieldnum(ProdBOM, ProdId));
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);

    // ProdRoute
    qbds3 = qbds2.addDataSource(tablenum(ProdRoute));
    qbds3.addLink(fieldnum(ProdBOM, ProdId), fieldnum(ProdRoute, ProdId));
    qbds3.addLink(fieldnum(ProdBOM, OprNum), fieldnum(ProdRoute, OprNum));
    qbds3.addRange(fieldnum(ProdRoute, OprPriority)).value(QueryValue(RouteOprPriority::Primary));
    qbds3.joinMode(JoinMode::InnerJoin);
    qbds3.fetchMode(QueryFetchMode::One2One);

    // NDX_ProdIdent_LabelItem
    qbds4 = qbds2.addDataSource(tablenum(NDXProdIdentLabelItem));
    qbds4.addLink(fieldnum(ProdBOM, ItemId), fieldnum(NDXProdIdentLabelItem, ItemId));
    qbds4.joinMode(JoinMode::InnerJoin);
    qbds4.fetchMode(QueryFetchMode::One2One);

    // NDX_ProdIdent_Label
    qbds5 = qbds4.addDataSource(tablenum(NDXProdIdentLabel));
    qbds5.relations(true);
    qbds5.joinMode(JoinMode::InnerJoin);
    qbds5.fetchMode(QueryFetchMode::One2One);

    // InventTable
    qbds6 = qbds2.addDataSource(tablenum(InventTable));
    qbds6.relations(true);
    qbds6.joinMode(JoinMode::InnerJoin);
    qbds6.fetchMode(QueryFetchMode::One2One);

    return q;
}

/// <summary>
/// 24.08.24
/// </summary>
/// <param name = "_prodTable">ProdTable</param>
/// <returns>Query</returns>
static Query queryFromProdTable2(ProdTable _prodTable = null)
{
    Query q = new Query();

    //QueryBuildDataSource qbdsRouteTest = q.addDataSource(tableNum(Route));
    //QueryBuildDataSource qbdsRouteOprTest = qbdsRouteTest.addDataSource(tableNum(RouteOpr));
    //qbdsRouteOprTest.relations(false);
    //qbdsRouteOprTest.addLink(fieldNum(Route, RouteId), fieldNum(RouteOpr,RouteRelation));
    //qbdsRouteOprTest.joinMode(JoinMode::InnerJoin);
    //qbdsRouteOprTest.fetchMode(QueryFetchMode::One2One);
    //QueryBuildDataSource qbdsProdRouteTest = qbdsRouteTest.addDataSource(tableNum(ProdRoute));
    //qbdsProdRouteTest.relations(false);
    //qbdsProdRouteTest.addLink(fieldNum(Route, OprId), fieldNum(ProdRoute, OprId));
    //qbdsProdRouteTest.joinMode(JoinMode::InnerJoin);
    //qbdsProdRouteTest.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsProdTable = q.addDataSource(tableNum(ProdTable));
    if (_prodTable)
    {
        qbdsProdTable.addRange(fieldnum(ProdTable, RecId)).value(queryValue(_prodTable.RecId));
    }

    QueryBuildDataSource qbdsProdRoute = qbdsProdTable.addDataSource(tableNum(ProdRoute));
    qbdsProdRoute.relations(true);
    qbdsProdRoute.joinMode(JoinMode::InnerJoin);
    qbdsProdRoute.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsRouteOpr = qbdsProdRoute.addDataSource(tableNum(RouteOpr));
    qbdsRouteOpr.joinMode(JoinMode::InnerJoin);
    qbdsRouteOpr.fetchMode(QueryFetchMode::One2One);
    qbdsRouteOpr.relations(false);
    qbdsRouteOpr.addLink(fieldNum(ProdRoute, RouteOprRefRecId), fieldNum(RouteOpr, RecId));
    qbdsRouteOpr.addLink(fieldNum(ProdRoute, OprId), fieldNum(RouteOpr, OprId));

    QueryBuildDataSource qbdsRoute = qbdsRouteOpr.addDataSource(tableNum(Route));
    qbdsRoute.relations(false);
    qbdsRoute.addLink(fieldNum(RouteOpr, RouteRelation), fieldNum(Route, RouteId));
    qbdsRoute.addLink(fieldNum(RouteOpr, OprId), fieldNum(Route, OprId));
    qbdsRoute.joinMode(JoinMode::InnerJoin);
    qbdsRoute.fetchMode(QueryFetchMode::One2One);

    //QueryBuildDataSource qbdsRouteProdRoute = qbdsRoute.addDataSource(tableNum(ProdRoute));
    //qbdsRouteProdRoute.relations(false);
    //qbdsRouteProdRoute.addLink(fieldNum(Route, OprId), fieldNum(ProdRoute, OprId));
    //qbdsRouteProdRoute.joinMode(JoinMode::ExistsJoin);
    //qbdsRouteProdRoute.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsNDXProdIdentProcedureLine1 = qbdsRoute.addDataSource(tableNum(NDXProdIdentProcedureLine1));
    qbdsNDXProdIdentProcedureLine1.relations(true);
    qbdsNDXProdIdentProcedureLine1.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureLine1.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsNDXProdIdentProcedureLine2 = qbdsNDXProdIdentProcedureLine1.addDataSource(tableNum(NDXProdIdentProcedureLine2));
    qbdsNDXProdIdentProcedureLine2.relations(true);
    qbdsNDXProdIdentProcedureLine2.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureLine2.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsNDXProdIdentTechnique = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(NDXProdIdentTechnique));
    qbdsNDXProdIdentTechnique.relations(true);
    qbdsNDXProdIdentTechnique.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentTechnique.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsUnitOfMeasureConversion = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(UnitOfMeasureConversion));
    qbdsUnitOfMeasureConversion.relations(true);
    qbdsUnitOfMeasureConversion.joinMode(JoinMode::OuterJoin);
    qbdsUnitOfMeasureConversion.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsNDXProdIdentLabel = qbdsNDXProdIdentProcedureLine2.addDataSource(tableNum(NDXProdIdentLabel));
    qbdsNDXProdIdentLabel.relations(true);
    qbdsNDXProdIdentLabel.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentLabel.fetchMode(QueryFetchMode::One2One);

    QueryBuildDataSource qbdsNDXProdIdentProcedureTable = qbdsNDXProdIdentProcedureLine1.addDataSource(tableNum(NDXProdIdentProcedureTable));
    qbdsNDXProdIdentProcedureTable.relations(true);
    qbdsNDXProdIdentProcedureTable.joinMode(JoinMode::InnerJoin);
    qbdsNDXProdIdentProcedureTable.fetchMode(QueryFetchMode::One2One);

    return q;
}

/// <summary>
/// PaffH 07.07.22
/// AX2009: classes.NDX_ProdIdent::fillControlPanelFromProdBOM_Q()
/// </summary>
/// <param name = "_q">Query</param>
/// <param name = "_prodTableBuffer">ProdTable</param>
/// <param name = "_contract">NDXProdStatusChangedGenerateTransportLabelEventContract</param>
/// <returns>int</returns>
static List fillControlPanelFromProdBOM_Q(Query _q, ProdTable _prodTableBuffer, NDXProdStatusChangedGenerateTransportLabelEventContract _contract)
{
    ProdBOM                         prodBOM;
    ProdTable                       prodTable;
    ProdRoute                       prodRoute;
    NDXProdIdentLabelItem         nDXProdIdentLabelItem;
    NDXProdIdentControlPanel       nDXProdIdentControlPanel;
    NDXProdIdentControlPanel       nDXProdIdentControlPanel2;
    NDXProdIdentLabel             nDXProdIdentLabel;
    InventTable                     inventTable;
    NDXProdIdentProcedureLine1    nDXProdIdentProcedureLine1;
    NDXProdIdentProcedureLine2    nDXProdIdentProcedureLine2;

    QueryRun    qr;
    Query       q2, q3;
    QueryRun    qr2, qr3;
    QueryBuildDataSource    qbds2_1, qbds2_2, qbds2_4;
    QueryBuildDataSource    qbds3_1, qbds3_2, qbds3_3;

    boolean                 lLVEtiFoundOK;
    int anz;
    List listContract = new List(Types::Class);

    void doSave(NDXProdIdentControlPanel lNDXProdIdentControlPanel)
    {
        if (lNDXProdIdentControlPanel.validateWrite())
        {
            lNDXProdIdentControlPanel.write();
            listContract.addEnd(NDXProdIdentControlPanel::populateToContract(lNDXProdIdentControlPanel));
            ++anz;
        }
    }
    ;
    qr = new QueryRun(_q);
    while (qr.next())
    {
        prodBOM                 = qr.get(tablenum(ProdBOM));
        prodTable               = qr.get(tablenum(ProdTable));
        prodRoute               = qr.get(tablenum(ProdRoute));
        nDXProdIdentLabelItem = qr.get(tablenum(NDXProdIdentLabelItem));
        nDXProdIdentLabel     = qr.get(tablenum(NDXProdIdentLabel));
        inventTable             = qr.get(tablenum(InventTable));
        //   ItemId of packaging
        nDXProdIdentControlPanel = NDXProdIdentControlPanel::findItemIdProdBOM(prodBOM.ItemId, prodRoute.OprNum, prodTable.ProdId, true);
        if (!nDXProdIdentControlPanel)
        {
            nDXProdIdentControlPanel.initValue();
            nDXProdIdentControlPanel.ProdId                = prodTable.ProdId;
            nDXProdIdentControlPanel.OprNum                = prodRoute.OprNum;
            nDXProdIdentControlPanel.ItemIdProdBOM         = prodBOM.ItemId;
            nDXProdIdentControlPanel.ControlPanelDataFrom  = NDXProdIdentControlPanelDataFrom::BoxLabelMapping;
            nDXProdIdentControlPanel.Host                  = _contract.ParmHost();
        }
        else
        {
            if (nDXProdIdentControlPanel.ControlPanelDataFrom == NDXProdIdentControlPanelDataFrom::ProdIdent)
            {
                nDXProdIdentControlPanel.ControlPanelDataFrom = NDXProdIdentControlPanelDataFrom::ProdIdentAndBoxLabelMapping;
            }
        }

        nDXProdIdentControlPanel.OprId                     = prodRoute.OprId;
        nDXProdIdentControlPanel.ItemId                    = prodTable.ItemId;
        nDXProdIdentControlPanel.Uebertragung_aus_AX = DateTimeUtil::utcNow();
        nDXProdIdentControlPanel.LabelId                   = nDXProdIdentLabelItem.LabelId;
        nDXProdIdentControlPanel.LabelIdBoxLabelMapping    = nDXProdIdentLabelItem.LabelId;
        nDXProdIdentControlPanel.RouteId                   = prodTable.RouteId;
        nDXProdIdentControlPanel.AnzahlEtiketten           = real2int(prodBOM.QtyInventCalc);
        //nDXProdIdentControlPanel.Menge                     = prodTable.QtySched;

        // Kennzeichnungsverfahren ermitteln
        // 1.Prüfung: Existiert eine Produktkennzeichnung zu diesem Artikel mit dem Arbeitsgang
        nDXProdIdentControlPanel.OprIdOK           = false;
        nDXProdIdentControlPanel.OprNumOK          = false;
        nDXProdIdentControlPanel.LabelFoundOK      = false;
        nDXProdIdentControlPanel.ProdIdentExists   = false;
        q2 = new Query();
        // NDX_ProdIdent_ProcedureTable
        qbds2_1 = q2.addDataSource(tablenum(NDXProdIdentProcedureTable));
        qbds2_1.addRange(fieldnum(NDXProdIdentProcedureTable, InventTable)).value(queryValue(InventTable::find(prodTable.ItemId).RecId));

        // NDXProdIdentProcedureLine2
        qbds2_2 = qbds2_1.addDataSource(tablenum(NDXProdIdentProcedureLine1));
        qbds2_2.relations(true);
        qbds2_2.joinMode(JoinMode::InnerJoin);
        qbds2_2.fetchMode(QueryFetchMode::One2One);
        //qbds2_2.addRange(fieldnum(NDX_ProdIdent_ProcedureLine1, OprNum)).value(QueryValue(prodRoute.OprNum));

        // Existiert eine Produktkennzeichnung?
        qr2 = new QueryRun(q2);
        nDXProdIdentControlPanel.ProdIdentExists = qr2.next();


        // Route
        qbds2_4 = qbds2_2.addDataSource(tablenum(Route));
        qbds2_4.relations(true);
        qbds2_4.joinMode(JoinMode::InnerJoin);
        qbds2_4.fetchMode(QueryFetchMode::One2One);
        qbds2_4.addRange(fieldnum(Route, OprId)).value(prodRoute.OprId);

        qr2 = new QueryRun(q2);
        while (qr2.next())
        {
            nDXProdIdentControlPanel.OprIdOK = true;
            nDXProdIdentProcedureLine1 = qr2.get(tablenum(NDXProdIdentProcedureLine1));
            // Entspricht der AG der Vorgabe
            if (nDXProdIdentProcedureLine1.Route != 0 &&
                Route::findRecId(nDXProdIdentProcedureLine1.Route).OprNum == prodRoute.OprNum)
            {
                nDXProdIdentControlPanel.OprNumOK = true;
                // Existiert zu der Arbeitsplanzuordnung ein Kennzeichnungsverfahren zu einem Verpackungsetikett
                q3 = new Query(q2);
                qbds3_1 = q3.dataSourceTable(tablenum(NDXProdIdentProcedureLine1));

                // nDXProdIdentProcedureLine2
                qbds3_2 = qbds3_1.addDataSource(tablenum(NDXProdIdentProcedureLine2));
                qbds3_2.relations(true);
                qbds3_2.joinMode(JoinMode::InnerJoin);
                qbds3_2.fetchMode(QueryFetchMode::One2One);

                // nDXProdIdentTechnique
                qbds3_3 = qbds3_2.addDataSource(tablenum(NDXProdIdentTechnique));
                qbds3_3.relations(true);
                qbds3_3.joinMode(JoinMode::InnerJoin);
                qbds3_3.fetchMode(QueryFetchMode::One2One);
                qbds3_3.addRange(fieldnum(NDXProdIdentTechnique, RelevantFor)).value(QueryValue(NDXProdIdentRelevantFor::Verpackungsetikett));

                qr3 = new QueryRun(q3);
                while (qr3.next())
                {
                    lLVEtiFoundOK = true;
                    nDXProdIdentProcedureLine2 = qr3.get(tablenum(NDXProdIdentProcedureLine2));

                    // Entspricht das Etikett der Vorgabe
                    if (NDXProdIdentLabel::findRecId(nDXProdIdentProcedureLine2.NDXProdIdentLabel).ID == nDXProdIdentLabelItem.LabelId)
                    {
                        nDXProdIdentControlPanel.LabelFoundOK = true;
                        nDXProdIdentControlPanel.TechniqueID                       = NDXProdIdentTechnique::findRecId(nDXProdIdentProcedureLine2.NDXProdIdentTechnique).ID;
                        nDXProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2  = nDXProdIdentProcedureLine2.RecId;
                    }
                    else
                    {
                        nDXProdIdentControlPanel.LabelIdProdIdent  = NDXProdIdentLabel::findRecId(nDXProdIdentProcedureLine2.NDXProdIdentLabel).ID;
                    }
                }
            }
        }

        NDXProdIdent::fillControlPanelAddition(nDXProdIdentControlPanel);
        NDXProdIdent::setStatus(nDXProdIdentControlPanel, _prodTableBuffer);

        ttsbegin;
        if (nDXProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2)
        {
            // Test: Existiert diese Festlegung bereits?
            nDXProdIdentControlPanel2 = NDXProdIdentControlPanel::findProcedureLine2(nDXProdIdentControlPanel.ProdId, nDXProdIdentControlPanel.RefRecIdProdIdent_ProcedureLine2, true);
            if (nDXProdIdentControlPanel2)
            {
                if (nDXProdIdentControlPanel2.ControlPanelDataFrom == NDXProdIdentControlPanelDataFrom::ProdIdent)
                {
                    nDXProdIdentControlPanel.ControlPanelDataFrom = NDXProdIdentControlPanelDataFrom::ProdIdentAndBoxLabelMapping;
                }
                nDXProdIdentControlPanel.LabelIdProdIdent     = nDXProdIdentControlPanel2.LabelIdProdIdent;
                buf2Buf(nDXProdIdentControlPanel, nDXProdIdentControlPanel2);
                doSave(nDXProdIdentControlPanel2);
            }
            else
            {
                doSave(nDXProdIdentControlPanel);
            }
        }
        else
        {
            doSave(nDXProdIdentControlPanel);
        }
        ttscommit;
    }
    return listContract;
}

/// <summary>
/// PaffH 07.07.22
/// AX2009: classes.NDX_ProdIdent::setStatus()
/// </summary>
/// <param name = "nDX_ProdIdentControlPanel">NDXProdIdentControlPanel</param>
/// <param name = "prodTableBuffer">ProdTable</param>
/// <param name = "forceBuild">boolean</param>
static void setStatus(NDXProdIdentControlPanel nDX_ProdIdentControlPanel,
                  ProdTable                 prodTableBuffer,
                  boolean                   forceBuild = false)

{
    NDXProdIdentParameters    nDX_ProdIdent_Parameters    = NDXProdIdentParameters::find();
    ProdStatusType prodStatusType = ProdStatusType::construct(prodTableBuffer);

    if (forceBuild)
    {
        nDX_ProdIdentControlPanel.ToSync    = NoYes::Yes;
        nDX_ProdIdentControlPanel.BTAction = nDX_ProdIdentControlPanel.BT_RecordId ? NDXProdIdentBTAction::update
                                                                                : NDXProdIdentBTAction::insert;
    }
    else if (prodStatusType.isAfterOrEqualTo(nDX_ProdIdent_Parameters.ProdStatusLabelErase))          // delete label entry
    {
        if (nDX_ProdIdentControlPanel.BT_RecordId)
        {
            nDX_ProdIdentControlPanel.BTAction = NDXProdIdentBTAction::delete;
            nDX_ProdIdentControlPanel.ToSync    = NoYes::Yes;
        }
        else
        {
            nDX_ProdIdentControlPanel.BTAction = NDXProdIdentBTAction::noAction;
            nDX_ProdIdentControlPanel.ToSync    = NoYes::No;
        }
    }
    else if (prodStatusType.isAfterOrEqualTo(nDX_ProdIdent_Parameters.ProdStatusLabelTransfer))  // print BT-label
    {
        if (nDX_ProdIdentControlPanel.BT_RecordId)
        {
            nDX_ProdIdentControlPanel.BTAction = NDXProdIdentBTAction::update;
        }
        else
        {
            nDX_ProdIdentControlPanel.BTAction = NDXProdIdentBTAction::insert;
        }
        nDX_ProdIdentControlPanel.ToSync    = NoYes::Yes;
    }
    else
    {
        nDX_ProdIdentControlPanel.BTAction = NDXProdIdentBTAction::noAction;
        nDX_ProdIdentControlPanel.ToSync    = NoYes::No;
    }
}

/// <summary>
/// PaffH 09.07.22
/// AX2009: classes.NDX_ProdIdent::queryFromProdBOM()
/// </summary>
/// <param name = "prodBOM">ProdBOM</param>
/// <returns>Query</returns>
static Query queryFromProdBOM(ProdBOM prodBOM)
{
    Query   q;
    QueryBuildDataSource    qbds1, qbds2, qbds3, qbds4, qbds5, qbds6;
    ;
    q = new Query();

    // ProdBOM
    qbds1 = q.addDataSource(tablenum(ProdBOM));
    qbds1.addRange(fieldnum(ProdBOM, RecId)).value(QueryValue(prodBOM.RecId));

    // ProdTable
    qbds2 = qbds1.addDataSource(tablenum(ProdTable));
    qbds2.addLink(fieldnum(ProdBOM, ProdId), fieldnum(ProdTable, ProdId));
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);

    // ProdRoute
    qbds3 = qbds1.addDataSource(tablenum(ProdRoute));
    qbds3.addLink(fieldnum(ProdBOM, ProdId), fieldnum(ProdRoute, ProdId));
    qbds3.addLink(fieldnum(ProdBOM, OprNum), fieldnum(ProdRoute, OprNum));
    qbds3.addRange(fieldnum(ProdRoute, OprPriority)).value(QueryValue(RouteOprPriority::Primary));
    qbds3.joinMode(JoinMode::InnerJoin);
    qbds3.fetchMode(QueryFetchMode::One2One);

    // NDX_ProdIdent_LabelItem
    qbds4 = qbds1.addDataSource(tablenum(NDXProdIdentLabelItem));
    qbds4.addLink(fieldnum(ProdBOM, ItemId), fieldnum(NDXProdIdentLabelItem, ItemId));
    qbds4.joinMode(JoinMode::InnerJoin);
    qbds4.fetchMode(QueryFetchMode::One2One);

    // NDX_ProdIdent_Label
    qbds5 = qbds4.addDataSource(tablenum(NDXProdIdentLabel));
    qbds5.relations(true);
    qbds5.joinMode(JoinMode::InnerJoin);
    qbds5.fetchMode(QueryFetchMode::One2One);

    // InventTable
    qbds6 = qbds1.addDataSource(tablenum(InventTable));
    qbds6.relations(true);
    qbds6.joinMode(JoinMode::InnerJoin);
    qbds6.fetchMode(QueryFetchMode::One2One);

    return q;
}

/// <summary>
/// PaffH 21.03.23
/// AX2009: classes.NDX_ProdIdent.getResult()
/// </summary>
/// <param name = "_classId">classId</param>
/// <param name = "_staticMethodName">str</param>
/// <param name = "_args">container</param>
/// <returns>container</returns>
public static container getResult(classId _classId, str _staticMethodName, container _args)
{
    SysDictClass        sysDictClass;
    anytype result;
    container           retContainer = conNull();
    str errorStr;
    sysDictClass = new SysDictClass(_classId);
    if (sysDictClass == null)
    {
        retContainer += '';
        retContainer += strFmt("@NDX:NDXClassNotLocalized", _classId);
        return retContainer;
    }
    new ExecutePermission().assert();
    try
    {
        if (_args)
        {
            str arg = conPeek(_args, 1);
            result = sysDictClass.callStatic(_staticMethodName, arg);
        }
        else
        {
            result = sysDictClass.callStatic(_staticMethodName);
        }
    }
    catch
    {
        errorStr = strfmt("@NDX:NDXClassMethodCouldNotBeExecuted", _classId, _staticMethodName, Con2Str(_args) );
        Error(errorStr); 
    }
    CodeAccessPermission::revertAssert();
    retContainer += any2Str(result);
    retContainer += errorStr;

    return retContainer;
}

