/// <summary>
/// PaffH 05.05.23
/// initilaize BT sync.-Action
/// AX2009: classes.NDX_ProdIdent.setSyncAction()
/// </summary>
/// <param name = "syncAction">syncAction</param>
/// <param name = "nDX_ProdIdentControlPanel">NDXProdIdentControlPanel</param>
/// TODO PaffH: Aufruf über Formular realisieren
static void setSyncAction(NDXProdIdentBTAction syncAction, NDXProdIdentControlPanel nDX_ProdIdentControlPanel)
{
    NDXProdIdentControlPanel   lNDX_ProdIdentControlPanel;
    NDXProdIdentControlPanel   lNDX_ProdIdentControlPanel2;
    MultiSelectionHelper    msh;
    Counter i;
    ;
    msh = MultiSelectionHelper::construct();
    msh.parmDatasource(FormDataUtil::getFormDataSource(nDX_ProdIdentControlPanel));
    lNDX_ProdIdentControlPanel = msh.getFirst();
    while (lNDX_ProdIdentControlPanel)
    {
        ++i;
        lNDX_ProdIdentControlPanel = msh.getNext();
    }

    if (box::okCancel(strfmt("@NDX:NDXBTSyncActionInit", i==1 ? "@NDXBase:NDXWillSingular": "@NDXBase:NDXWillPlural", i, syncAction), DialogButton::Ok) == DialogButton::Cancel)
    {
        return;
    }

    i = 0;
    lNDX_ProdIdentControlPanel = msh.getFirst();
    while (lNDX_ProdIdentControlPanel)
    {
        ++i;
        lNDX_ProdIdentControlPanel2 = NDXProdIdentControlPanel::findRecId(lNDX_ProdIdentControlPanel.RecId, true);
        lNDX_ProdIdentControlPanel2.BTAction = syncAction;
        lNDX_ProdIdentControlPanel2.modifiedField(fieldnum(NDXProdIdentControlPanel, BTAction));
        if (lNDX_ProdIdentControlPanel2.validateWrite())
        {
            ttsbegin;
            lNDX_ProdIdentControlPanel2.update();
            ttscommit;
        }
        lNDX_ProdIdentControlPanel = msh.getNext();
    }
    info(strfmt("@NDXBase:NDXUpdateWasPerformedOnRecords", i));
}

