/// <summary>
/// PaffH 27.08.23
/// copy product identifier for item
/// </summary>
/// <param name = "inventTableCopyTo">InventTable</param>
/// <param name = "procedureLine1CopyTo">NDXProdIdentProcedureLine1</param>
/// <param name = "procedureLine1CopyFrom">NDXProdIdentProcedureLine1</param>
/// <param name = "lTest">boolean</param>
/// <returns>boolean</returns>
[SuppressBPWarning('BPParameterNotUsed','Parameter "lTest"')]
static boolean copyFrom(InventTable inventTableCopyTo,
    NDXProdIdentProcedureLine1   procedureLine1CopyTo,
    NDXProdIdentProcedureLine1   procedureLine1CopyFrom,
    boolean lTest = false)
{
    NDXProdIdentProcedureTable        lNDX_ProdIdent_ProcedureTable;
    NDXProdIdentProcedureLine1        lNDX_ProdIdent_ProcedureLine1CopyTo;
    NDXProdIdentProcedureLine2        lNDX_ProdIdent_ProcedureLine2CopyFrom,  lNDX_ProdIdent_ProcedureLine2CopyTo;
    NDXProdIdentLine22LabelArea       lNDX_ProdIdent_Line22LabelAreaCopyFrom, lNDX_ProdIdent_Line22LabelAreaCopyTo;
    NDXProdIdentBlock2ItemId          lNDX_ProdIdent_Block2ItemIdCopyFrom,    lNDX_ProdIdent_Block2ItemIdCopyTo;
    NDXProdIdentBlock2LabelArea       lNDX_ProdIdent_Block2LabelAreaCopyFrom, lNDX_ProdIdent_Block2LabelAreaCopyTo;


    boolean     lCopyOk = true;

    if (inventTableCopyTo.RecId == 0)
    {
        Error("@NDX:NDXProdIdentCopyToError1");
        lCopyOk = false;
    }
    if (procedureLine1CopyTo.Route == 0 || procedureLine1CopyTo.RouteVersion == 0)
    {
        Error("@NDX:NDXProdIdentCopyToError2");
        lCopyOk = false;
    }
    if (procedureLine1CopyFrom.Route == 0 || procedureLine1CopyFrom.RouteVersion == 0)
    {
        Error("@NDX:NDXProdIdentCopyToError3");
        lCopyOk = false;
    }

    if (lCopyOk)
    {
        ttsbegin;
        // NDX_ProdIdent_ProcedureTable
        lNDX_ProdIdent_ProcedureTable = NDXProdIdentProcedureTable::findInventTable(inventTableCopyTo.RecId, true);
        if (!lNDX_ProdIdent_ProcedureTable)
        {
            lNDX_ProdIdent_ProcedureTable.InventTable = inventTableCopyTo.RecId;
            //NDXProdIdent::showInfo(strFmt('Insert [NDXProdIdentProcedureTable] [%1]', InventTable::findRecId(lNDX_ProdIdent_ProcedureTable.InventTable)), lTest);
            lNDX_ProdIdent_ProcedureTable.insert();
        }
        //else
        //{
        //    NDXProdIdent::showInfo(strFmt('Exists [NDXProdIdentProcedureTable] [%1]', InventTable::findRecId(lNDX_ProdIdent_ProcedureTable.InventTable)), lTest);
        //}

        // NDX_ProdIdent_ProcedureLine1
        lNDX_ProdIdent_ProcedureLine1CopyTo = NDXProdIdentProcedureLine1::find(lNDX_ProdIdent_ProcedureTable.RecId,
                                                                             procedureLine1CopyTo.RouteVersion,
                                                                             procedureLine1CopyTo.Route, true);
        if (!lNDX_ProdIdent_ProcedureLine1CopyTo)
        {
            lNDX_ProdIdent_ProcedureLine1CopyTo.NDXProdIdentProcedureTable = lNDX_ProdIdent_ProcedureTable.RecId;
            lNDX_ProdIdent_ProcedureLine1CopyTo.RouteVersion  = procedureLine1CopyTo.RouteVersion;
            lNDX_ProdIdent_ProcedureLine1CopyTo.Route = procedureLine1CopyTo.Route;
            lNDX_ProdIdent_ProcedureLine1CopyTo.insert();
            //NDXProdIdent::showInfo(strFmt('Insert [NDXProdIdentProcedureLine1] Route [%1] RouteVersion [%2]', Route::findRecId(lNDX_ProdIdent_ProcedureLine1CopyTo.Route).RouteId, RouteVersion::findRecId(lNDX_ProdIdent_ProcedureLine1CopyTo.RouteVersion).RouteId), lTest);
        }
        //else
        //{
        //    NDXProdIdent::showInfo(strFmt('Exists [NDXProdIdentProcedureLine1] Route [%1] RouteVersion [%2]', Route::findRecId(lNDX_ProdIdent_ProcedureLine1CopyTo.Route).RouteId, RouteVersion::findRecId(lNDX_ProdIdent_ProcedureLine1CopyTo.RouteVersion).RouteId), lTest);
        //}
        // Freigabe beim kopierten Artikel entfernen
        if (lNDX_ProdIdent_ProcedureLine1CopyTo.Freigabe == NoYes::Yes)
        {
            lNDX_ProdIdent_ProcedureLine1CopyTo.Freigabe = NoYes::No;
            ttsbegin;
            lNDX_ProdIdent_ProcedureLine1CopyTo.update();
            ttscommit;
        }

        // Kennzeichnungsverfahren zum Arbeitsplan/gang durchlaufen
        while select lNDX_ProdIdent_ProcedureLine2CopyFrom
        where    lNDX_ProdIdent_ProcedureLine2CopyFrom.NDXProdIdentProcedureLine1 == procedureLine1CopyFrom.RecId
        {
            // Ausgabewerte zum Kennzeichnungsverfahren
            while select lNDX_ProdIdent_Block2ItemIdCopyFrom
            where    lNDX_ProdIdent_Block2ItemIdCopyFrom.IDSort                             == lNDX_ProdIdent_ProcedureLine2CopyFrom.IDSort
                &&   lNDX_ProdIdent_Block2ItemIdCopyFrom.NDXProdIdentProcedureLine1   == lNDX_ProdIdent_ProcedureLine2CopyFrom.NDXProdIdentProcedureLine1
            {
                lNDX_ProdIdent_Block2ItemIdCopyTo = NDXProdIdentBlock2ItemId::find(lNDX_ProdIdent_ProcedureLine1CopyTo.RecId,
                                                                                 lNDX_ProdIdent_Block2ItemIdCopyFrom.IDSort,
                                                                                 lNDX_ProdIdent_Block2ItemIdCopyFrom.SubId,
                                                                                 lNDX_ProdIdent_Block2ItemIdCopyFrom.NDXProdIdentBlockTable,
                                                                                 lNDX_ProdIdent_Block2ItemIdCopyFrom.BlockIdFieldName, true);
                if (!lNDX_ProdIdent_Block2ItemIdCopyTo)
                {
                    buf2Buf(lNDX_ProdIdent_Block2ItemIdCopyFrom, lNDX_ProdIdent_Block2ItemIdCopyTo);
                    lNDX_ProdIdent_Block2ItemIdCopyTo.NDXProdIdentProcedureLine1   = lNDX_ProdIdent_ProcedureLine1CopyTo.RecId;
                    lNDX_ProdIdent_Block2ItemIdCopyTo.insert();
                    //NDXProdIdent::showInfo(strFmt('Insert [NDXProdIdentBlock2ItemId] [%1]', lNDX_ProdIdent_Block2ItemIdCopyTo.BlockIdFieldName), lTest);
                }
                //else
                //{
                //    NDXProdIdent::showInfo(strFmt('Exists [NDXProdIdentBlock2ItemId] [%1]', lNDX_ProdIdent_Block2ItemIdCopyTo.BlockIdFieldName), lTest);
                //}
            }

            // DS-Anlage darf erst hier erfolgen (ansonsten würden schon alles Block-ID's angelegt)
            lNDX_ProdIdent_ProcedureLine2CopyTo = NDXProdIdentProcedureLine2::find(lNDX_ProdIdent_ProcedureLine1CopyTo.RecId, lNDX_ProdIdent_ProcedureLine2CopyFrom.IDSort, true);
            if (!lNDX_ProdIdent_ProcedureLine2CopyTo)
            {
                buf2Buf(lNDX_ProdIdent_ProcedureLine2CopyFrom, lNDX_ProdIdent_ProcedureLine2CopyTo);
                lNDX_ProdIdent_ProcedureLine2CopyTo.NDXProdIdentProcedureLine1 = lNDX_ProdIdent_ProcedureLine1CopyTo.RecId;
                lNDX_ProdIdent_ProcedureLine2CopyTo.insert();
                //NDXProdIdent::showInfo(strFmt('Insert [NDXProdIdentProcedureLine2] [%1]', NDXProdIdentTechnique::findRecId(lNDX_ProdIdent_ProcedureLine2CopyTo.NDXProdIdentTechnique).Name), lTest);
            }
            //else
            //{
            //    NDXProdIdent::showInfo(strFmt('Exists [NDXProdIdentProcedureLine2] [%1]', NDXProdIdentTechnique::findRecId(lNDX_ProdIdent_ProcedureLine2CopyTo.NDXProdIdentTechnique).Name), lTest);
            //}

            // Beschriftungsflächenzuordnung zum Kennzeichnungsverfahren
            while select lNDX_ProdIdent_Line22LabelAreaCopyFrom
            where    lNDX_ProdIdent_Line22LabelAreaCopyFrom.NDXProdIdentProcedureLine2 == lNDX_ProdIdent_ProcedureLine2CopyFrom.RecId
            {
                lNDX_ProdIdent_Line22LabelAreaCopyTo = NDXProdIdentLine22LabelArea::find(lNDX_ProdIdent_ProcedureLine2CopyTo.RecId, lNDX_ProdIdent_Line22LabelAreaCopyFrom.NDXProdIdentLabelAreaTable, true);
                if (!lNDX_ProdIdent_Line22LabelAreaCopyTo)
                {
                    buf2Buf(lNDX_ProdIdent_Line22LabelAreaCopyFrom, lNDX_ProdIdent_Line22LabelAreaCopyTo);
                    lNDX_ProdIdent_Line22LabelAreaCopyTo.NDXProdIdentProcedureLine2 = lNDX_ProdIdent_ProcedureLine2CopyTo.RecId;
                    lNDX_ProdIdent_Line22LabelAreaCopyTo.insert();
                    //NDXProdIdent::showInfo(strFmt('Insert [NDXProdIdentLine22LabelArea] [%1]', NDXProdIdentLabelAreaTable::findRecId(lNDX_ProdIdent_Line22LabelAreaCopyTo.NDXProdIdentLabelAreaTable).Id), lTest);
                }
                //else
                //{
                //    NDXProdIdent::showInfo(strFmt('Exists [NDXProdIdentLine22LabelArea] [%1]', NDXProdIdentLabelAreaTable::findRecId(lNDX_ProdIdent_Line22LabelAreaCopyTo.NDXProdIdentLabelAreaTable).Id), lTest);
                //}

                // Beschriftungsflächen-Zuordnung
                while select lNDX_ProdIdent_Block2LabelAreaCopyFrom
                where    lNDX_ProdIdent_Block2LabelAreaCopyFrom.NDXProdIdentLine22LabelArea == lNDX_ProdIdent_Line22LabelAreaCopyFrom.RecId
                {
                    lNDX_ProdIdent_Block2LabelAreaCopyTo = NDXProdIdentBlock2LabelArea::find(lNDX_ProdIdent_Line22LabelAreaCopyTo.RecId,
                                                                                           lNDX_ProdIdent_Block2LabelAreaCopyFrom.NDXProdIdentBlockTable,
                                                                                           lNDX_ProdIdent_Block2LabelAreaCopyFrom.AllRest, true);
                    if (!lNDX_ProdIdent_Block2LabelAreaCopyTo)
                    {
                        buf2Buf(lNDX_ProdIdent_Block2LabelAreaCopyFrom, lNDX_ProdIdent_Block2LabelAreaCopyTo);
                        lNDX_ProdIdent_Block2LabelAreaCopyTo.NDXProdIdentLine22LabelArea = lNDX_ProdIdent_Line22LabelAreaCopyTo.RecId;
                        lNDX_ProdIdent_Block2LabelAreaCopyTo.insert();
                        //NDXProdIdent::showInfo(strFmt('Insert [NDXProdIdentBlock2LabelArea] [%1]', lNDX_ProdIdent_Block2LabelAreaCopyTo.RecId), lTest);
                    }
                    //else
                    //{
                    //    NDXProdIdent::showInfo(strFmt('Exists [NDXProdIdentBlock2LabelArea] [%1]', lNDX_ProdIdent_Block2LabelAreaCopyTo.RecId), lTest);
                    //}
                }
            }
        }
        //if (lTest)
        //{
        //    ttsabort;
        //}
        //else
        //{
        ttscommit;
        //}
        info(strfmt("@NDX:NDXProductIdentifierForItemHasBeenCreated", inventTableCopyTo.ItemId ));
    }
    return lCopyOk;
}

/// <summary>
/// PaffH 05.08.24
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_showInfo">boolean</param>
/// <returns>container</returns>
static container checkPhantom(ItemId _itemId, boolean _showInfo = false)
{
    NDXPhantomOprNumAdd nDXPhantomOprNumAdd;
    const int oprNumAdd = 10;

    void checkRouteVersion(BOM _bomLocal)
    {
        Route route;
        RouteVersion routeVersion = RouteVersion::findActive(_bomLocal.ItemId, NDXHelperCommon::SystemDateGet(), 0, _bomLocal.inventDim());
        while select route
            where route.RouteId == routeVersion.RouteId
        {
            if (route.OprPriority == RouteOprPriority::Primary)
            {
                nDXPhantomOprNumAdd += oprNumAdd;
            }
            if (_showInfo)
            {
                info(strFmt("@NDX:NDXCheckRouteVersionInfo", route.OprNum, route.RouteId, route.OprId, route.OprPriority, nDXPhantomOprNumAdd));
            }
        }
    }

    void checkPhantomRecursive(ItemId _itemIdLocal, int _levelLocal)
    {
        BOM bomLocal;
        BOMVersion bomVersionLocal = BOMVersion::findValidActive(_itemIdLocal);
        while select bomLocal
            where bomLocal.BOMId == bomVersionLocal.BOMId
        {
            if (_showInfo)
            {
                Info(strFmt(NDXPlaceholderConstants::SquareBrackets1Space2Space3, _levelLocal, bomLocal.ItemId, bomLocal.BOMType));
            }
            if (bomLocal.BOMType == BOMType::Phantom)
            {
                checkPhantomRecursive(bomLocal.ItemId, _levelLocal + 1);
                checkRouteVersion(bomLocal);
            }
        }
    }

    BOMVersion bomVersion = BOMVersion::findValidActive(_itemId);
    BOM bom;
    int level = 1;
    NDXHasPhantomBOM nDXHasPhantomBOM = false;
    while select bom
        where bom.BOMId == bomVersion.BOMId
    {
        if (_showInfo)
        {
            Info(strFmt(NDXPlaceholderConstants::SquareBrackets1Space2Space3, level, bom.ItemId, bom.BOMType));
        }
        if (bom.BOMType == BOMType::Phantom)
        {
            nDXHasPhantomBOM = true;
            checkPhantomRecursive(bom.ItemId, level + 1);
            checkRouteVersion(bom);
        }
    }
    return [nDXHasPhantomBOM, nDXPhantomOprNumAdd];
}

/// <summary>
/// PaffH 02.10.24
/// change label id
/// </summary>
/// <param name = "nDX_ProdIdent_ProcedureLine2">NDXProdIdentProcedureLine2</param>
/// <param name = "nDXProdIdentLabelFrom">NDXProdIdentLabel</param>
/// <param name = "nDXProdIdentLabelTo">NDXProdIdentLabel</param>
static void changeLabelId(NDXProdIdentProcedureLine2 nDX_ProdIdent_ProcedureLine2,
                      NDXProdIdentLabel nDXProdIdentLabelFrom,
                      NDXProdIdentLabel nDXProdIdentLabelTo)
{
    NDXProdIdentProcedureLine2    l_NDX_ProdIdent_ProcedureLine2;
    FormDataSource  fds;
    Counter anz1, anz2, anz3;
    Query q;
    QueryRun qr;
    QueryBuildDataSource qbds1;
    str info;
    DialogButton btnChoice;
    boolean lChange = true;

    // change label id
    boolean changeLabelId2(NDXProdIdentProcedureLine2 l2_NDX_ProdIdent_ProcedureLine2)
    {
        NDXProdIdentProcedureLine2 l3_NDX_ProdIdent_ProcedureLine2;
        NDXProdIdentLabel nDXProdIdentLabel;
        select firstonly forUpdate l3_NDX_ProdIdent_ProcedureLine2
        where l3_NDX_ProdIdent_ProcedureLine2.RecId == l2_NDX_ProdIdent_ProcedureLine2.RecId
            join nDXProdIdentLabel 
            where nDXProdIdentLabel.RecId == l3_NDX_ProdIdent_ProcedureLine2.NDXProdIdentLabel;
        if (nDXProdIdentLabel.ID == nDXProdIdentLabelFrom.ID)
        {
            if (lChange)
            {
                ttsbegin;
                l3_NDX_ProdIdent_ProcedureLine2.NDXProdIdentLabel = nDXProdIdentLabelTo.RecId;
                l3_NDX_ProdIdent_ProcedureLine2.update();
                ttscommit;
            }
            return true;
        }
        return false;
    }

    if (!nDXProdIdentLabelFrom.ID || !nDXProdIdentLabelTo.ID || nDXProdIdentLabelFrom.ID == nDXProdIdentLabelTo.ID)
    {
        CheckFailed("@NDX:NDXChangeLabelMapping_2");        // Bitte geben Sie an, welche Etiketten-Id zu ändern ist!
        return;
    }
    if (FormDataUtil::isFormDataSource(nDX_ProdIdent_ProcedureLine2))
    {
        fds = FormDataUtil::getFormDataSource(nDX_ProdIdent_ProcedureLine2);
    }
    if (fds && fds.anyMarked())
    {
        l_NDX_ProdIdent_ProcedureLine2 = fds.getFirst(1);
        while (l_NDX_ProdIdent_ProcedureLine2)
        {
            ++anz2;
            if (l_NDX_ProdIdent_ProcedureLine2.NDXProdIdentLabel == nDXProdIdentLabelFrom.RecId)
            {
                ++anz1;
            }
            l_NDX_ProdIdent_ProcedureLine2 = fds.getNext();
        }
        if (!anz1)
        {
            info = strfmt("@NDX:NDXChangeLabelMapping_3", anz2, nDXProdIdentLabelFrom.ID);                   // Unter den [%1] markierten Datensätzen wurde keiner mit dem Etikettentyp [%2] lokalisiert!
            Warning(info);
        }
        info = strfmt("@NDX:NDXChangeLabelMapping_4", anz1, nDXProdIdentLabelFrom.ID, nDXProdIdentLabelTo.ID);            // Sollen die [%1] markierten Etikettenzuordnungen von [%2] nach [%3] geändert werden?
        btnChoice = box::yesNoCancel(info, DialogButton::Cancel);
        if (!anz1 || btnChoice != DialogButton::Yes)
        {
            return;
        }
        l_NDX_ProdIdent_ProcedureLine2 = fds.getFirst(1);
        while (l_NDX_ProdIdent_ProcedureLine2)
        {
            ++anz2;
            if (l_NDX_ProdIdent_ProcedureLine2.NDXProdIdentLabel == nDXProdIdentLabelFrom.RecId)
            {
                if (changeLabelId2(l_NDX_ProdIdent_ProcedureLine2))
                {
                    ++anz3;
                }
            }
            l_NDX_ProdIdent_ProcedureLine2 = fds.getNext();
        }
    }
    else
    {
        q = new Query();
        qbds1 = q.addDataSource(tablenum(NDXProdIdentProcedureLine2));
        qbds1.addRange(fieldnum(NDXProdIdentProcedureLine2, NDXProdIdentLabel)).value(queryValue(nDXProdIdentLabelFrom.RecId));
        qbds1.addSelectionField(fieldnum(NDXProdIdentProcedureLine2, RecId), SelectionField::Count);
        qr = new QueryRun(q);
        qr.next();
        l_NDX_ProdIdent_ProcedureLine2 = qr.get(tablenum(NDXProdIdentProcedureLine2));
        anz1 = int642int(l_NDX_ProdIdent_ProcedureLine2.RecId);
        info = strfmt("@NDX:NDXChangeLabelMapping", anz1, nDXProdIdentLabelFrom.ID, nDXProdIdentLabelTo.ID);        // Sollen alle [%1] Etikettenzuordnungen von [%2] nach [%3] geändert werden?\n(Bei 'Nein' wird nur das Etikett des aktuellen Eintrag geändert.)
        info = strFmtLB(info);
        btnChoice = box::yesNoCancel(info, DialogButton::Cancel);
        if (btnChoice == DialogButton::Cancel)
        {
            return;
        }
        else if (btnChoice == DialogButton::No)
        {
            if (changeLabelId2(nDX_ProdIdent_ProcedureLine2))
            {
                ++anz3;
            }
        }
        else
        {
            q = new Query();
            qbds1 = q.addDataSource(tablenum(NDXProdIdentProcedureLine2));
            qbds1.addRange(fieldnum(NDXProdIdentProcedureLine2, NDXProdIdentLabel)).value(queryValue(nDXProdIdentLabelFrom.RecId));
            qr = new QueryRun(q);
            while (qr.next())
            {
                l_NDX_ProdIdent_ProcedureLine2 = qr.get(tablenum(NDXProdIdentProcedureLine2));
                if (changeLabelId2(l_NDX_ProdIdent_ProcedureLine2))
                {
                    ++anz3;
                }
            }
        }
    }
    info(strfmt("@NDX:NDXChangeLabelMapping_5", anz3));         // Insgesamt wurden [%1] Etikettenzuordnungen geändert.
    if (fds)
    {
        fds.executeQuery();
    }
}
